trait Shape {
    fn area(&self) -> u32;
}

struct Square {
    side: u32,
}

impl Square {
    fn area(&self) -> u32 {
        self.side * self.side
    }
}

fn print_area<T: Shape>(shape: &T) {
    println!("{}", shape.area());
}

fn main() {
    print_area(&Square { side: 3 });
}

